mapper.select:
/*selectMasterCmClArCloseConfirmList*/
SELECT X.SITE, X.TAX_BILL_NO, X.BUYER_CODE, X.AGENT_CODE, X.TAX_IRS_NO, X.AR_TYPE, X.AR_TYPE_TEXT, X.AR_CLOSE_MONTH, X.ISSUE_DATE, X.BM_LEGACY_USER_ID, X.BM_USER_NAME, X.PM_LEGACY_USER_ID, X.PM_USER_NAME, X.KEP_DEPT, X.KEP_DEPT_NAME, X.COM_NAME_LOC, X.CUSTOMER_NAME, X.AR_BUYER_AMT, DECODE(X.RANK, 1, X.AR_TAX_AMT, 0) AS AR_TAX_AMT, X.AR_AGENT_AMT, (X.AR_BUYER_AMT - X.AR_AGENT_AMT) AS AR_SUM, X.AR_RATE, X.CONFIRM_LEGACY_USER_ID, X.CONFIRM_USER_NAME, X.ADD_DATE, X.ERP_SEND_YN, X.ERP_SEND_DATE FROM (
SELECT MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='SR01' AND FLAG ='Y' AND CODE = ARLIST.SITE)) AS SITE, ARLIST.TAX_BILL_NO AS TAX_BILL_NO, GR.BUYER AS BUYER_CODE, GR.AGENT AS AGENT_CODE, AR.IRS_NO AS TAX_IRS_NO, MAX(ARLIST.AR_TYPE) AS AR_TYPE, MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='ARCL01' AND FLAG ='Y' AND CODE = ARLIST.AR_TYPE)) AS AR_TYPE_TEXT, MAX(ARLIST.AR_CLOSE_MONTH) AS AR_CLOSE_MONTH, MAX(ARLIST.ISSUE_DATE) AS ISSUE_DATE, (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND MAIN_CLERK = 'Y')) AS BM_LEGACY_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND MAIN_CLERK = 'Y')) AS BM_USER_NAME, (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND PRIORITY = 'Y')) AS PM_LEGACY_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND PRIORITY = 'Y')) AS PM_USER_NAME, ARLIST.KEP_DEPT AS KEP_DEPT, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE ='KRKORE0001' AND FLAG ='Y' AND CODE = ARLIST.KEP_DEPT) AS KEP_DEPT_NAME, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.BUYER) AS COM_NAME_LOC, MAX(AR.CUSTOMER_NAME) AS CUSTOMER_NAME, SUM(GR.LOGIS_AMT) AS AR_BUYER_AMT, MAX(ARLIST.AR_TAX_AMT) AS AR_TAX_AMT, MAX(ARLIST.AR_AGENT_AMT) AS AR_AGENT_AMT, MAX(DECODE(ARLIST.AR_AGENT_AMT,0,100,ROUND((ARLIST.AR_BUYER_AMT - ARLIST.AR_AGENT_AMT) / ARLIST.AR_BUYER_AMT) *100,2)) || '%' AS AR_RATE, MAX(ARLIST.CONFIRM_LEGACY_USER_ID) AS CONFIRM_LEGACY_USER_ID, MAX(ARLIST.CONFIRM_USER_NAME) AS CONFIRM_USER_NAME, MAX(TO_CHAR(ARLIST.ADD_DATE,'YY/MM/DD')) AS ADD_DATE, MAX(ARLIST.ERP_SEND_YN) AS ERP_SEND_YN, MAX(ARLIST.ERP_SEND_DATE) AS ERP_SEND_DATE, DENSE_RANK() OVER (PARTITION BY ARLIST.KEP_DEPT, ARLIST.TAX_BILL_NO ORDER BY ARLIST.KEP_DEPT, ARLIST.TAX_BILL_NO, AR.IRS_NO, GR.BUYER) AS RANK FROM AR_CLOSE_CONFIRM_LIST ARLIST, ICOMGRDT GR, KEPTARDT AR WHERE 1=1 AND ARLIST.TAX_BILL_NO = GR.LOGIS_TAX_BILL_NO AND GR.AP_CLOSE_DEPT = ARLIST.KEP_DEPT AND GR.AR_TAX_BILL_NO = AR.TAX_BILL_NO AND GR.AR_CLOSE_DEPT = AR.DEPT_CODE AND GR.STATUS IN ('C','R') AND GR.LOGIS_AMT != 0 AND AR.STATUS IN ('C','R') AND ARLIST.AR_CLOSE_MONTH = #{st_from_date} AND ARLIST.AR_TYPE = 'LG_A' -- 물류비(자동)
AND ARLIST.KEP_DEPT IN
#{dept_cd}
AND GR.BUYER = #{st_buyer_code}
AND REPLACE(AR.IRS_NO, '-','') LIKE '%' || REPLACE(#{st_irs_no},'-','') || '%'
AND ARLIST.CONFIRM_USER_NAME LIKE '%' || #{st_user_name} || '%'
AND ARLIST.ERP_SEND_YN = #{st_erp_send_yn}
AND ARLIST.TAX_BILL_NO = #{st_tax_bill_no}
GROUP BY AR.IRS_NO, GR.BUYER, GR.AGENT, ARLIST.TAX_BILL_NO,ARLIST.KEP_DEPT
SELECT MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='SR01' AND FLAG ='Y' AND CODE = SITE)) AS SITE, TAX_BILL_NO AS TAX_BILL_NO, BUYER_CODE AS BUYER_CODE, MAX(AGENT_CODE) AS AGENT_CODE, TAX_IRS_NO AS TAX_IRS_NO, AR_TYPE AS AR_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='ARCL01' AND FLAG ='Y' AND CODE = AR_TYPE) AS AR_TYPE_TEXT, MAX(AR_CLOSE_MONTH) AS AR_CLOSE_MONTH, MAX(ISSUE_DATE) AS ISSUE_DATE, MAX(BM_LEGACY_USER_ID) AS BM_LEGACY_USER_ID, MAX(BM_USER_NAME) AS BM_USER_NAME, MAX(PM_LEGACY_USER_ID) AS PM_LEGACY_USER_ID, MAX(PM_USER_NAME) AS PM_USER_NAME, KEP_DEPT AS KEP_DEPT, MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE ='KRKORE0001' AND FLAG ='Y' AND CODE = KEP_DEPT)) AS KEP_DEPT_NAME, MAX(COM_NAME_LOC) AS COM_NAME_LOC, MAX(CUSTOMER_NAME) AS CUSTOMER_NAME, SUM(AR_BUYER_AMT) AS AR_BUYER_AMT, SUM(AR_TAX_AMT) AS AR_TAX_AMT, SUM(AR_AGENT_AMT) AS AR_AGENT_AMT, DECODE(SUM(AR_AGENT_AMT),NULL,100,ROUND(((SUM(AR_BUYER_AMT - AR_AGENT_AMT)) / SUM(AR_BUYER_AMT)) *100,2)) || '%' AS AR_RATE, MAX(CONFIRM_LEGACY_USER_ID) AS CONFIRM_LEGACY_USER_ID, MAX(CONFIRM_USER_NAME) AS CONFIRM_USER_NAME, MAX(TO_CHAR(ADD_DATE,'YY/MM/DD')) AS ADD_DATE, MAX(ERP_SEND_YN) AS ERP_SEND_YN, MAX(ERP_SEND_DATE) AS ERP_SEND_DATE, 1 AS RANK FROM AR_CLOSE_CONFIRM_LIST WHERE 1=1 AND AR_CLOSE_MONTH = #{st_from_date} AND AR_TYPE != 'LG_A'
AND KEP_DEPT IN
#{dept_cd}
AND AR_TYPE = #{st_ar_type}
AND BUYER_CODE = #{st_buyer_code}
AND REPLACE(TAX_IRS_NO, '-','') LIKE '%' || REPLACE(#{st_irs_no},'-','') || '%'
AND CONFIRM_USER_NAME LIKE '%' || #{st_user_name} || '%'
AND ERP_SEND_YN = #{st_erp_send_yn}
AND TAX_BILL_NO = #{st_tax_bill_no}
GROUP BY BUYER_CODE, TAX_BILL_NO, KEP_DEPT, TAX_IRS_NO, AR_TYPE
SELECT MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='SR01' AND FLAG ='Y' AND CODE = ARLIST.SITE)) AS SITE, ARLIST.TAX_BILL_NO AS TAX_BILL_NO, GR.BUYER AS BUYER_CODE, GR.AGENT AS AGENT_CODE, AR.IRS_NO AS TAX_IRS_NO, MAX(ARLIST.AR_TYPE) AS AR_TYPE, MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='ARCL01' AND FLAG ='Y' AND CODE = ARLIST.AR_TYPE)) AS AR_TYPE_TEXT, MAX(ARLIST.AR_CLOSE_MONTH) AS AR_CLOSE_MONTH, MAX(ARLIST.ISSUE_DATE) AS ISSUE_DATE, (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND MAIN_CLERK = 'Y')) AS BM_LEGACY_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND MAIN_CLERK = 'Y')) AS BM_USER_NAME, (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND PRIORITY = 'Y')) AS PM_LEGACY_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = (SELECT KEP_USER_ID FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND STATUS = 'C' AND BUYER = GR.BUYER AND PRIORITY = 'Y')) AS PM_USER_NAME, ARLIST.KEP_DEPT AS KEP_DEPT, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE ='KRKORE0001' AND FLAG ='Y' AND CODE = ARLIST.KEP_DEPT) AS KEP_DEPT_NAME, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.BUYER) AS COM_NAME_LOC, MAX(AR.CUSTOMER_NAME) AS CUSTOMER_NAME, SUM(GR.LOGIS_AMT) AS AR_BUYER_AMT, MAX(ARLIST.AR_TAX_AMT) AS AR_TAX_AMT, MAX(ARLIST.AR_AGENT_AMT) AS AR_AGENT_AMT, MAX(DECODE(ARLIST.AR_AGENT_AMT,0,100,ROUND((ARLIST.AR_BUYER_AMT - ARLIST.AR_AGENT_AMT) / ARLIST.AR_BUYER_AMT) *100,2)) || '%' AS AR_RATE, MAX(ARLIST.CONFIRM_LEGACY_USER_ID) AS CONFIRM_LEGACY_USER_ID, MAX(ARLIST.CONFIRM_USER_NAME) AS CONFIRM_USER_NAME, MAX(TO_CHAR(ARLIST.ADD_DATE,'YY/MM/DD')) AS ADD_DATE, MAX(ARLIST.ERP_SEND_YN) AS ERP_SEND_YN, MAX(ARLIST.ERP_SEND_DATE) AS ERP_SEND_DATE, DENSE_RANK() OVER (PARTITION BY ARLIST.KEP_DEPT, ARLIST.TAX_BILL_NO ORDER BY ARLIST.KEP_DEPT, ARLIST.TAX_BILL_NO, AR.IRS_NO, GR.BUYER) AS RANK FROM AR_CLOSE_CONFIRM_LIST ARLIST, ICOMGRDT GR, KEPTARDT AR WHERE 1=1 AND ARLIST.TAX_BILL_NO = GR.LOGIS_TAX_BILL_NO AND GR.AP_CLOSE_DEPT = ARLIST.KEP_DEPT AND GR.AR_TAX_BILL_NO = AR.TAX_BILL_NO AND GR.AR_CLOSE_DEPT = AR.DEPT_CODE AND GR.STATUS IN ('C','R') AND GR.LOGIS_AMT != 0 AND AR.STATUS IN ('C','R') AND ARLIST.AR_CLOSE_MONTH = #{st_from_date} AND ARLIST.AR_TYPE = 'LG_A'
AND ARLIST.KEP_DEPT IN
#{dept_cd}
AND GR.BUYER = #{st_buyer_code}
AND REPLACE(AR.IRS_NO, '-','') LIKE '%' || REPLACE(#{st_irs_no},'-','') || '%'
AND ARLIST.CONFIRM_USER_NAME LIKE '%' || #{st_user_name} || '%'
AND ARLIST.ERP_SEND_YN = #{st_erp_send_yn}
AND ARLIST.TAX_BILL_NO = #{st_tax_bill_no}
GROUP BY AR.IRS_NO, GR.BUYER, GR.AGENT, ARLIST.TAX_BILL_NO,ARLIST.KEP_DEPT
UNION SELECT MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='SR01' AND FLAG ='Y' AND CODE = SITE)) AS SITE, TAX_BILL_NO AS TAX_BILL_NO, BUYER_CODE AS BUYER_CODE, MAX(AGENT_CODE) AS AGENT_CODE, TAX_IRS_NO AS TAX_IRS_NO, AR_TYPE AS AR_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='ARCL01' AND FLAG ='Y' AND CODE = AR_TYPE) AS AR_TYPE_TEXT, MAX(AR_CLOSE_MONTH) AS AR_CLOSE_MONTH, MAX(ISSUE_DATE) AS ISSUE_DATE, MAX(BM_LEGACY_USER_ID) AS BM_LEGACY_USER_ID, MAX(BM_USER_NAME) AS BM_USER_NAME, MAX(PM_LEGACY_USER_ID) AS PM_LEGACY_USER_ID, MAX(PM_USER_NAME) AS PM_USER_NAME, KEP_DEPT AS KEP_DEPT, MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE ='KRKORE0001' AND FLAG ='Y' AND CODE = KEP_DEPT)) AS KEP_DEPT_NAME, MAX(COM_NAME_LOC) AS COM_NAME_LOC, MAX(CUSTOMER_NAME) AS CUSTOMER_NAME, SUM(AR_BUYER_AMT) AS AR_BUYER_AMT, SUM(AR_TAX_AMT) AS AR_TAX_AMT, SUM(AR_AGENT_AMT) AS AR_AGENT_AMT, DECODE(SUM(AR_AGENT_AMT),NULL,100,ROUND(((SUM(AR_BUYER_AMT - AR_AGENT_AMT)) / SUM(AR_BUYER_AMT)) *100,2)) || '%' AS AR_RATE, MAX(CONFIRM_LEGACY_USER_ID) AS CONFIRM_LEGACY_USER_ID, MAX(CONFIRM_USER_NAME) AS CONFIRM_USER_NAME, MAX(TO_CHAR(ADD_DATE,'YY/MM/DD')) AS ADD_DATE, MAX(ERP_SEND_YN) AS ERP_SEND_YN, MAX(ERP_SEND_DATE) AS ERP_SEND_DATE, 1 AS RANK FROM AR_CLOSE_CONFIRM_LIST WHERE 1=1 AND AR_CLOSE_MONTH = #{st_from_date} AND AR_TYPE != 'LG_A'
AND KEP_DEPT IN
#{dept_cd}
AND AR_TYPE = #{st_ar_type}
AND BUYER_CODE = #{st_buyer_code}
AND REPLACE(TAX_IRS_NO, '-','') LIKE '%' || REPLACE(#{st_irs_no},'-','') || '%'
AND CONFIRM_USER_NAME LIKE '%' || #{st_user_name} || '%'
AND ERP_SEND_YN = #{st_erp_send_yn}
AND TAX_BILL_NO = #{st_tax_bill_no}
GROUP BY BUYER_CODE, TAX_BILL_NO, KEP_DEPT, TAX_IRS_NO, AR_TYPE
) X ORDER BY X.AR_TYPE, X.TAX_BILL_NO, X.KEP_DEPT, X.CONFIRM_USER_NAME

mapper.update:
	/*updateMasterCmClArCloseConfirm_cancle*/

		UPDATE 
	    	BILL_CLOSE_USER_LIST
	    	SET CLOSE_CMPL_YN = 'N'
			WHERE 1=1
			AND BILL_CLOSE_MONTH = #{AR_CLOSE_MONTH}
			AND LEGACY_USER_ID = #{CONFIRM_LEGACY_USER_ID}
			AND BUYER_CODE = #{BUYER_CODE}						
			AND CLOSE_TYPE = DECODE(#{AR_TYPE}, 'AR','AR','LG')
			AND CLOSE_CMPL_YN = 'Y'


    		AND AGENT_CODE = #{AGENT_CODE}

/*updateMasterCmClArCloseConfirm_confirm*/

	UPDATE AR_CLOSE_CONFIRM_LIST
	SET 
	    AR_CLOSE_CONFIRM_YN    = 'Y'
	  , AR_CLOSE_CONFIRM_DATE  = SYSDATE
	WHERE 1=1
	AND AR_CLOSE_MONTH = #{AR_CLOSE_MONTH}
	AND BUYER_CODE = #{BUYER_CODE}
	AND KEP_DEPT     = #{KEP_DEPT}		
	AND AR_TYPE = #{AR_TYPE}			


		    AND TAX_IRS_NO = #{TAX_IRS_NO}

/*updateMasterCmClArCloseConfirm_submit*/

	UPDATE
	BILL_CLOSE_USER_LIST
	SET
		CLOSE_CMPL_YN = 'N',
		CHANGE_DATE = SYSDATE
	WHERE 1=1
	AND LEGACY_USER_ID = #{CONFIRM_LEGACY_USER_ID}
	AND CLOSE_TYPE = DECODE(#{AR_TYPE}, 'AR','AR','LG')
	AND BILL_CLOSE_MONTH = #{AR_CLOSE_MONTH}
	AND BUYER_CODE = #{BUYER_CODE}


    AND AGENT_CODE = #{AGENT_CODE}
